function cfg = cameraConfig
% Camera profile used by imager.m / GrabSave.m. Do not edit this file for your rig: put the lines
% that differ into rigConfig.m (copy rigConfig_example.m), which runs at the end and is git-ignored.
%
% Profiles:
%   'grasshopper3' : FLIR Grasshopper3 (GigE/USB3) through the Image Acquisition Toolbox
%                    'pointgrey' adaptor (FlyCapture2). The strobe is the adaptor property Strobe2
%                    (GPIO2, red wire).  This is the original setup (300x480 px, 10 Hz).
%   'blackflyS'    : FLIR Blackfly S (e.g. BFS-U3-244S8M, Sony IMX540 5320x4600) through the
%                    'gentl' adaptor (Spinnaker GenTL producer). Binning, crop, exposure, frame
%                    rate and the strobe output are GenICam features; setupCamera.m sets them every
%                    time the imager starts (the camera keeps its last binning while it has power).
%
% Settings (cfg fields):
%   profile, adaptor, deviceID, format, fallbackFormat   which camera and pixel format
%   fps, exposure_ms, gain_dB                            frame rate, exposure per frame, gain
%   binning       hardware binning factor on both axes: 1, 2 or 4 on the BFS-U3-244S8 (1 = none;
%                 [] leaves the camera as it is)
%   binningMode   'Sum' (adds signal: 4 collects 16x the light per pixel of 1) or 'Average'
%   roiSensor     field of view in UNBINNED sensor pixels: [width height] centred, or
%                 [xoffset yoffset width height]. The frame is this divided by the binning, so
%                 changing cfg.binning keeps the same field of view at a different sampling.
%   roi           alternative crop in BINNED pixels ([w h] centred or [x y w h]); overrides
%                 roiSensor when not empty. A rigConfig.m that sets only cfg.roi gets exactly
%                 that (cfg.roi = [] alone means the full frame, as before roiSensor existed).
%   strobeLine    output that pulses once per frame ('Line2' = red wire on the Blackfly S)
%   throughputLimit   USB link limit in bytes/s, [] = camera default
%
% Notes for the Blackfly S:
%   * One trial of total_time seconds at cfg.fps frames/s is held in RAM once (GrabSave streams the
%     frames out of the acquisition buffer as they arrive; checkFrameMemory refuses a trial that does
%     not fit in the free physical memory). Per 191 s trial at 15 Hz in Mono16 with the default
%     roiSensor [2800 2800]: binning 4 -> 688x688 px, 2.5 GB; binning 2 -> 1376x1376 px, 10.1 GB;
%     binning 1 -> 2752x2752 px, 40 GB (does not fit: shrink roiSensor or shorten the trial).
%   * Frame rate: the sensor is read row by row (FLIR's table: about 27 us per sensor row in Mono16, so
%     7 fps for the full 4600 rows and about 13 fps for 2752 rows at binning 1). Binning done by the
%     camera's image processor does not speed this up; fewer rows do. setupCamera prints the rate the
%     camera can deliver; when that is below cfg.fps a trial keeps its duration and has fewer frames.
%   * Mono16 (12-bit ADC) is strongly preferred over Mono8 for 2-4 % dF/F signals. Mono16 at 15 Hz
%     needs a USB 3 port (the rear ports on the QI-Lab PC); on a USB 2 link the frame rate collapses.
%   * Strobe: the BFS 6-pin GPIO has Line0 = opto-isolated input (black), Line1 = opto-isolated
%     output (white, open collector: needs a pull-up resistor to show a pulse), Line2 = red and
%     Line3 = green non-isolated bidirectional 3.3 V lines. The NI USB-6008 ai0 threshold in run2.m
%     is 1 V, so Line2 or Line3 driven as 'Output' with LineSource 'ExposureActive' works directly.
%   * GenICam enumeration/boolean values are written as strings ('Off', 'True'); setupCamera.m
%     tries the common spellings and reports what it could not set, so check the printout once.

global Mstate
profile = 'blackflyS';     % default profile: 'grasshopper3' or 'blackflyS' (rigConfig.m may set cfg.profile)

UNSET = -1;                % marks cfg.roi / cfg.roiSensor as 'not set by rigConfig.m'
cfg = profileDefaults(profile); defaults = cfg; cfg.roi = UNSET; cfg.roiSensor = UNSET;
if exist('rigConfig', 'file') == 2
    % rigConfig.m also holds Mstate lines (for configureMstate / updateMonitor). Only its camera lines
    % count here: cameraConfig runs for every trial and must not reset what was changed in the GUI.
    savedMstate = Mstate;
    rigConfig;
    if (ischar(cfg.profile) || isstring(cfg.profile)) && ~strcmpi(cfg.profile, profile)   % the rig uses the other camera: start again from that profile's defaults
        cfg = profileDefaults(char(cfg.profile)); defaults = cfg; cfg.roi = UNSET; cfg.roiSensor = UNSET;
        rigConfig;
    end
    Mstate = savedMstate;
end
% Crop: what rigConfig.m set wins. cfg.roi alone (any value, [] included) switches the roiSensor default
% off, so a rigConfig.m written before roiSensor existed keeps its meaning.
roiSet = ~isequal(cfg.roi, UNSET); sensorSet = ~isequal(cfg.roiSensor, UNSET);
if ~roiSet, cfg.roi = defaults.roi; end
if ~sensorSet
    if roiSet, cfg.roiSensor = []; else, cfg.roiSensor = defaults.roiSensor; end
end
cfg.profile = char(cfg.profile);
cfg = checkConfig(cfg, fieldnames(defaults));


function cfg = profileDefaults(profile)
cfg.profile = profile;
cfg.fps = 15;                  % frames per second requested from the camera (the analysis uses the measured strobe times)
cfg.exposure_ms = 30;          % exposure per frame in ms (must be < 1000/fps)
cfg.gain_dB = 0;
switch lower(profile)
    case 'grasshopper3'
        cfg.adaptor = 'pointgrey';
        cfg.deviceID = 1;
        cfg.format = 'F7_Mono16_480x300_Mode5';          % 4x4 binned Format7 mode
        cfg.fallbackFormat = 'F7_Mono16_960x600_Mode1';
        cfg.binning = [];                                 % binning is part of the Format7 mode
        cfg.binningMode = '';
        cfg.roiSensor = [];
        cfg.roi = [];                                     % [xoffset yoffset width height], [] = full frame
        cfg.strobeLine = 'Strobe2';                       % pointgrey adaptor property
        cfg.throughputLimit = [];
    case 'blackflys'
        cfg.adaptor = 'gentl';
        cfg.deviceID = 1;
        cfg.format = 'Mono16';                            % 12-bit data in 16-bit frames
        cfg.fallbackFormat = 'Mono8';
        cfg.binning = 4;                                  % 1, 2 or 4 on the BFS-U3-244S8 (4 -> 1328x1150 px full frame)
        cfg.binningMode = 'Sum';                          % 'Sum' (adds signal) or 'Average'
        cfg.roiSensor = [2800 2800];                      % field of view in unbinned sensor pixels, centred; frame = this / binning (688x688 px at binning 4)
        cfg.roi = [];                                     % or a crop in binned pixels ([w h] centred, [x y w h] placed); overrides roiSensor
        cfg.strobeLine = 'Line2';                         % GenICam line used as the frame strobe (red wire)
        cfg.throughputLimit = 380e6;                      % bytes/s; [] leaves the camera default (43e6 is the USB 2 figure)
    otherwise
        error('cameraConfig:profile', 'unknown camera profile ''%s'' (use ''blackflyS'' or ''grasshopper3'')', profile);
end


function cfg = checkConfig(cfg, known)
% A setting that is not one of the known fields is a typo that would otherwise be ignored silently
% (cfg.bin instead of cfg.binning). Warnings are printed on the first call only: imager.m clears this
% function when it starts, so they appear once per imager start and not for every trial.
persistent quiet
first = isempty(quiet); quiet = true;
extra = setdiff(fieldnames(cfg), known);
if ~isempty(extra) && first
    for k = 1:numel(extra)
        near = known(strncmpi(known, extra{k}, min(3, numel(extra{k}))));
        hint = '';
        if ~isempty(near), hint = sprintf(' Did you mean cfg.%s?', strjoin(near(:)', ' or cfg.')); end
        warning('cameraConfig:unknownSetting', 'cfg.%s (set in rigConfig.m) is not a camera setting and is IGNORED.%s', extra{k}, hint);
    end
end
b = cfg.binning;
if ~isempty(b) && ~(isnumeric(b) && isscalar(b) && b >= 1 && b == round(b))
    error('cameraConfig:binning', 'cfg.binning must be one whole number (1, 2 or 4 on the Blackfly S); it is %s', describe(b));
end
names = {'roi', 'roiSensor'};
for k = 1:numel(names)
    v = cfg.(names{k});
    if ~(isnumeric(v) && any(numel(v) == [0 2 4]) && all(v(:) >= 0) && all(v(:) == round(v(:))))
        error('cameraConfig:roi', 'cfg.%s must be [] (none), [width height] (centred) or [xoffset yoffset width height] in whole pixels; it is %s', names{k}, describe(v));
    end
end
if ~(isnumeric(cfg.fps) && isscalar(cfg.fps) && cfg.fps > 0) || ~(isnumeric(cfg.exposure_ms) && isscalar(cfg.exposure_ms) && cfg.exposure_ms > 0)
    error('cameraConfig:timing', 'cfg.fps and cfg.exposure_ms must be positive numbers');
end
if cfg.exposure_ms >= 1000 / cfg.fps && first
    warning('cameraConfig:exposure', 'cfg.exposure_ms = %g ms does not fit in one frame at cfg.fps = %g (%.1f ms): the camera will lower the frame rate', cfg.exposure_ms, cfg.fps, 1000 / cfg.fps);
end


function s = describe(v)
if isnumeric(v) || islogical(v), s = mat2str(v); elseif ischar(v), s = ['''' v '''']; else, s = ['a ' class(v)]; end
